    .fetch_one(&pool)
    .await
    .unwrap();
    assert_eq!(start_date, "2026-01-15");
    assert_eq!(end_date, "2026-01-16");

    // A subsequent GET must parse back as an all-day event with the same dates.
    let (get_status, _, get_body) = request(
        build_caldav_router(accounts),
