        commoncal_backend::ics::NormalizedTiming::AllDay {
            start_date: chrono::NaiveDate::from_ymd_opt(2026, 1, 15).unwrap(),
            end_date: chrono::NaiveDate::from_ymd_opt(2026, 1, 16).unwrap(),
        }
    );
    let _ = (temp_dir, user_id);
}

